tool_input.command:
B=<repo>; cd "$B"; python3 - <<'PY'
p='docs/artifacts/daemon-status.html'
h=open(p).read()
uri=open('.tmp/diagram.svg').read().strip()
mmd=open('.tmp/diagram.mmd').read().strip()

# 1. CSS for the figure + details block, appended before </style>
css = """
  figure.flow { margin: 1.75rem 0 0; }
  figure.flow .frame {
    background: var(--card); border: 1px solid var(--rule); border-radius: 8px;
    padding: 1rem; overflow-x: auto;
  }
  figure.flow img { display: block; width: 100%; height: auto; min-width: 34rem; }
  figure.flow figcaption {
    color: var(--muted); font-size: .83rem; margin-top: .7rem; max-width: 52rem;
  }
  details.src { margin: 1rem 0 0; }
  details.src summary {
    cursor: pointer; font-size: .85rem; color: var(--accent); font-weight: 600;
  }
  details.src pre { margin-top: .6rem; max-height: 26rem; overflow: auto; }
  @media (prefers-color-scheme: dark) {
    figure.flow .frame { background: #f6f4f0; }
  }
"""
assert '</style>' in h
h = h.replace('</style>', css + '</style>', 1)

# 2. The diagram section, inserted after the legend, before section 01
anchor = '<h2><span class="n">01</span>The pipeline, stage by stage</h2>'
assert anchor in h

section = f"""<h2><span class="n">00</span>The whole picture, in one diagram</h2>
<p class="lede">
  Green is real. Amber is real with a stated gap. Red is promised somewhere and not implemented.
  Dashed boxes are the gaps, each pointing at the stage it affects and naming its bead.
  Everything below this diagram is the same information in words — read the diagram, then
  drill into whichever box you care about.
</p>

<figure class="flow">
  <div class="frame">
    <img src="{uri}" alt="Flowchart of the beadle-daemon mail pipeline. An email arrives and passes through eight stages: poll mailbox, transport trust check, sender x-permission check, produce a plan, recipe signature check, build contract and create ethos mission, spawn worker, record and reply. Failing the trust check, the permission check, or the signature check drops or rejects the message. Six dashed callout boxes mark gaps: the Trusted trust level depends on IMAP being localhost with nothing verifying it (beadle-hv7i); the production planner regex appears in no test (beadle-ivtd); LLMPlanner is a stub so mail can only pick a recipe (beadle-tl6); the worker has no OS sandbox (unfiled); no signed audit log exists despite ARCHITECTURE.md claiming one (beadle-623); and no init or sign tooling exists so a fresh operator cannot reach the signature stage at all (beadle-7gm).">
  </div>
  <figcaption>
    Read top to bottom: an email only reaches the worker by clearing three independent gates.
    The three grey terminals are where mail stops. Note that four of the six gaps cluster on the
    two stages in the middle &mdash; producing a plan and verifying the recipe &mdash; which is
    where the daemon decides <em>what to do</em> rather than <em>whether to proceed</em>.
  </figcaption>
</figure>

<details class="src">
  <summary>Diagram source (Mermaid) &mdash; edit this, not the rendered image</summary>
<pre><code>{mmd.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')}</code></pre>
</details>

{anchor}"""

h = h.replace(anchor, section, 1)
open(p,'w').write(h)
print('written:', len(h), 'bytes')
PY
